INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Avena con Manzana y Canela', 'Desayuno reconfortante, bajo índice glucémico. Ideal para control de glucosa.', 'desayuno', 'facil', 10, 'sistema', '[{"nombre":"Avena en hojuelas","cantidad":40,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1.5},{"nombre":"Manzana picada","cantidad":120,"unidad":"g","smae_id":"frutas_medias_cho","racionesSmae":1},{"nombre":"Leche descremada","cantidad":240,"unidad":"ml","smae_id":"lacteos_descremados_bajos_grasas","racionesSmae":1},{"nombre":"Canela en polvo","cantidad":2,"unidad":"g"},{"nombre":"Nueces picadas","cantidad":10,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":0.5}]'::jsonb, '["Calienta la leche descremada a fuego medio sin dejar que hierva.","Agrega la avena y cocina por 5 minutos revolviendo constantemente.","Incorpora la manzana picada y la canela.","Cocina 2 minutos más y sirve coronado con las nueces."]'::jsonb, 1, '{"kcal":310,"cho":48,"prot":14,"grasas":7,"fibra":6,"sodio":85}'::jsonb, '{"cargaGlicemica":"baja","alergenos":["Gluten","Lácteos"],"vitaminas":[],"aptaParaDietas":["Vegetariana"]}'::jsonb, '["Diabetes 2","Diabetes 1","Dislipidemia","Hipotiroidismo"]'::jsonb, '["baja_en_sodio","baja_en_grasa"]'::jsonb, '["alta_en_fibra","bajo_indice_glucemico","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Huevos Revueltos con Espinaca y Champiñones', 'Alto en proteína y hierro. Perfecto para control de peso y ganancia muscular.', 'desayuno', 'facil', 12, 'sistema', '[{"nombre":"Huevo entero","cantidad":2,"unidad":"piezas","smae_id":"carnes_medias_grasas","racionesSmae":2},{"nombre":"Espinaca fresca","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Champiñones rebanados","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Tortilla de maíz","cantidad":1,"unidad":"pieza","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1},{"nombre":"Aceite de oliva","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5}]'::jsonb, '["Calienta el aceite de oliva en un sartén antiadherente a fuego medio.","Saltea los champiñones 2 minutos hasta que doren.","Agrega la espinaca y cocina hasta que se reduzca.","Bate los huevos y viértelos sobre las verduras.","Revuelve suavemente hasta obtener la consistencia deseada.","Sirve acompañado de la tortilla de maíz caliente."]'::jsonb, 1, '{"kcal":320,"cho":24,"prot":20,"grasas":17,"fibra":3,"sodio":220}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Huevo"],"vitaminas":["Hierro"],"aptaParaDietas":[]}'::jsonb, '["Lesión muscular","Hipotiroidismo","SOP","Osteoporosis/artrosis"]'::jsonb, '["sin_lactosa"]'::jsonb, '["alta_en_proteina","rica_en_hierro","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Smoothie Verde Antiinflamatorio', 'Bebida antioxidante rica en vitaminas. Ideal para artritis y condiciones inflamatorias.', 'desayuno', 'facil', 5, 'sistema', '[{"nombre":"Espinaca baby","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Plátano congelado","cantidad":60,"unidad":"g","smae_id":"frutas_medias_cho","racionesSmae":1},{"nombre":"Leche de almendras","cantidad":240,"unidad":"ml","smae_id":"lacteos_descremados_bajos_grasas","racionesSmae":1},{"nombre":"Jengibre fresco rallado","cantidad":5,"unidad":"g"},{"nombre":"Semillas de chía","cantidad":10,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":0.5}]'::jsonb, '["Coloca todos los ingredientes en la licuadora.","Licua por 1 minuto a velocidad alta hasta obtener una mezcla homogénea.","Si queda muy espeso, agrega un poco más de leche de almendras.","Sirve inmediatamente para conservar los nutrientes."]'::jsonb, 1, '{"kcal":195,"cho":28,"prot":7,"grasas":7,"fibra":8,"sodio":60}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Nueces/Cacahuates"],"vitaminas":[],"aptaParaDietas":["Vegetariana"]}'::jsonb, '["Artritis","Osteoporosis/artrosis","Gastritis","Hipertensión"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio"]'::jsonb, '["antiinflamatoria","antioxidante","rapida","alta_en_fibra"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Pechuga de Pollo a la Plancha con Ensalada Mediterránea', 'Almuerzo alto en proteína magra con grasas saludables. Control de peso y masa muscular.', 'almuerzo', 'facil', 20, 'sistema', '[{"nombre":"Pechuga de pollo","cantidad":120,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":3},{"nombre":"Lechuga mixta","cantidad":80,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":2},{"nombre":"Tomate cherry","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Pepino","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Aceite de oliva","cantidad":10,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":1},{"nombre":"Arroz integral","cantidad":80,"unidad":"g cocido","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":2}]'::jsonb, '["Sazona la pechuga con hierbas finas, ajo en polvo y pimienta.","Cocina a la plancha 6-7 minutos por cada lado a fuego medio.","Mientras, prepara la ensalada mezclando lechuga, tomate y pepino.","Adereza con aceite de oliva y limón al gusto.","Sirve el pollo rebanado sobre la ensalada con el arroz al lado."]'::jsonb, 1, '{"kcal":420,"cho":38,"prot":40,"grasas":14,"fibra":4,"sodio":150}'::jsonb, '{"cargaGlicemica":"baja","alergenos":[],"vitaminas":["Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Diabetes 2","Diabetes 1","Dislipidemia","Lesión muscular","Hipotiroidismo","SOP"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio"]'::jsonb, '["alta_en_proteina","baja_en_grasa","bajo_indice_glucemico"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Salmón al Horno con Brócoli y Camote', 'Rico en omega-3 y antioxidantes. Excelente para salud cardiovascular y articular.', 'almuerzo', 'media', 30, 'sistema', '[{"nombre":"Filete de salmón","cantidad":120,"unidad":"g","smae_id":"carnes_medias_grasas","racionesSmae":3},{"nombre":"Brócoli","cantidad":100,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":2},{"nombre":"Camote cocido","cantidad":80,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":2},{"nombre":"Aceite de oliva","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5},{"nombre":"Limón","cantidad":1,"unidad":"pieza"}]'::jsonb, '["Precalienta el horno a 200°C.","Coloca el salmón en una charola con papel encerado, rocía con aceite y limón.","Agrega el brócoli y camote en cubos alrededor del salmón.","Hornea 18-22 minutos hasta que el salmón se desmenuce fácilmente.","Sazona con hierbas frescas al servir."]'::jsonb, 1, '{"kcal":450,"cho":35,"prot":38,"grasas":18,"fibra":6,"sodio":120}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Pescado"],"vitaminas":["Omega 3","Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Artritis","Osteoporosis/artrosis","Dislipidemia","Hipertensión"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio"]'::jsonb, '["rica_en_omega3","antiinflamatoria","alta_en_proteina"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Tacos de Nopal con Frijoles y Queso Panela', 'Comida mexicana saludable, alta en fibra y baja en grasa. Apta para diabetes.', 'almuerzo', 'facil', 15, 'sistema', '[{"nombre":"Nopales asados","cantidad":100,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":2},{"nombre":"Frijoles de la olla","cantidad":80,"unidad":"g","smae_id":"leguminosas","racionesSmae":1},{"nombre":"Queso panela","cantidad":40,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":1},{"nombre":"Tortilla de maíz","cantidad":2,"unidad":"piezas","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":2},{"nombre":"Salsa verde","cantidad":20,"unidad":"ml"},{"nombre":"Cilantro y cebolla","cantidad":15,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":0.5}]'::jsonb, '["Asa los nopales en un comal hasta que pierdan la baba (5-7 min).","Calienta los frijoles y machácalos ligeramente.","Corta el queso panela en cubos o tiras.","Calienta las tortillas y arma los tacos con nopales, frijoles y queso.","Corona con salsa verde, cilantro y cebolla picada."]'::jsonb, 1, '{"kcal":365,"cho":45,"prot":22,"grasas":10,"fibra":10,"sodio":180}'::jsonb, '{"cargaGlicemica":"baja","alergenos":["Lácteos"],"vitaminas":[],"aptaParaDietas":[]}'::jsonb, '["Diabetes 2","Diabetes 1","Dislipidemia","Gastritis"]'::jsonb, '["sin_gluten","baja_en_grasa"]'::jsonb, '["mexicana","alta_en_fibra","bajo_indice_glucemico","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Crema de Lentejas con Zanahoria', 'Sopa reconfortante alta en hierro y fibra. Fácil de digerir, ideal para gastritis.', 'almuerzo', 'facil', 25, 'sistema', '[{"nombre":"Lentejas","cantidad":80,"unidad":"g","smae_id":"leguminosas","racionesSmae":1.5},{"nombre":"Zanahoria","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Cebolla","cantidad":30,"unidad":"g"},{"nombre":"Aceite de oliva","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5},{"nombre":"Pan integral tostado","cantidad":1,"unidad":"rebanada","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1}]'::jsonb, '["Sofríe la cebolla picada en aceite de oliva hasta transparentar.","Agrega las lentejas, zanahoria picada y 500ml de agua.","Cocina a fuego medio-bajo por 20 minutos hasta que las lentejas estén suaves.","Licua hasta obtener una crema suave. Ajusta sal si es necesario.","Sirve caliente con el pan integral tostado."]'::jsonb, 1, '{"kcal":340,"cho":50,"prot":18,"grasas":7,"fibra":12,"sodio":90}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Gluten"],"vitaminas":["Hierro"],"aptaParaDietas":["Vegana","Vegetariana"]}'::jsonb, '["Gastritis","Diabetes 2","Artritis","Hipertensión"]'::jsonb, '["sin_lactosa","baja_en_sodio","baja_en_grasa"]'::jsonb, '["alta_en_fibra","rica_en_hierro","facil_digestion","dieta_blanda"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Bowl de Quinoa con Pollo y Aguacate', 'Comida completa y equilibrada. Excelente perfil de aminoácidos para masa muscular.', 'almuerzo', 'media', 25, 'sistema', '[{"nombre":"Quinoa cocida","cantidad":80,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":2},{"nombre":"Pechuga de pollo desmenuzada","cantidad":90,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":2.5},{"nombre":"Aguacate","cantidad":40,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":1},{"nombre":"Espinaca fresca","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Tomate cherry","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Limón y cilantro","cantidad":10,"unidad":"g"}]'::jsonb, '["Cocina la quinoa según las instrucciones del paquete y deja enfriar.","Cocina la pechuga de pollo y desmenúzala.","En un bowl, coloca la quinoa como base.","Agrega el pollo, espinaca, tomates cherry y aguacate en rebanadas.","Adereza con limón y cilantro fresco al gusto."]'::jsonb, 1, '{"kcal":440,"cho":40,"prot":35,"grasas":16,"fibra":7,"sodio":130}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":["Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Lesión muscular","Hipotiroidismo","SOP","Dislipidemia"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio"]'::jsonb, '["alta_en_proteina","completa","bowl"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Caldo de Pollo con Verduras (Sin Sal Añadida)', 'Caldo casero bajo en sodio. Reconfortante e ideal para hipertensión y gastritis.', 'almuerzo', 'facil', 35, 'sistema', '[{"nombre":"Pechuga de pollo con hueso","cantidad":100,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":2.5},{"nombre":"Calabacita","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Chayote","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Zanahoria","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Elote","cantidad":50,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1},{"nombre":"Cilantro y limón","cantidad":10,"unidad":"g"}]'::jsonb, '["Coloca la pechuga con hueso en una olla con 1 litro de agua fría.","Agrega las verduras cortadas en trozos grandes.","Cocina a fuego medio por 30 minutos. NO agregues sal.","Retira el pollo, deshébralo y regrésalo al caldo.","Sirve con cilantro fresco y gotas de limón."]'::jsonb, 2, '{"kcal":220,"cho":18,"prot":25,"grasas":5,"fibra":4,"sodio":45}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":["Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Hipertensión","Gastritis","Artritis","Osteoporosis/artrosis"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio","baja_en_grasa"]'::jsonb, '["baja_en_sodio","facil_digestion","reconfortante","dieta_blanda"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Wrap de Atún con Verduras Frescas', 'Cena ligera y rápida, alta en proteína y omega-3.', 'cena', 'facil', 10, 'sistema', '[{"nombre":"Atún en agua (escurrido)","cantidad":80,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":2},{"nombre":"Tortilla de harina integral","cantidad":1,"unidad":"pieza","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1.5},{"nombre":"Lechuga","cantidad":30,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Jitomate rebanado","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Aguacate","cantidad":30,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":0.75}]'::jsonb, '["Escurre bien el atún y desmenúzalo.","Calienta ligeramente la tortilla en un comal.","Coloca la lechuga, jitomate, atún y aguacate sobre la tortilla.","Enrolla firmemente y corta a la mitad.","Sirve con gotas de limón si lo deseas."]'::jsonb, 1, '{"kcal":310,"cho":26,"prot":24,"grasas":13,"fibra":4,"sodio":200}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Gluten","Pescado"],"vitaminas":["Omega 3","Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Dislipidemia","Lesión muscular","Hipotiroidismo","SOP"]'::jsonb, '["sin_lactosa"]'::jsonb, '["alta_en_proteina","rica_en_omega3","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Tortilla Española de Claras con Verduras', 'Cena proteica baja en grasa. Perfecta para control de colesterol.', 'cena', 'facil', 15, 'sistema', '[{"nombre":"Claras de huevo","cantidad":4,"unidad":"piezas","smae_id":"carnes_bajas_grasas","racionesSmae":2},{"nombre":"Calabacita rallada","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Pimiento rojo picado","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Cebolla picada","cantidad":20,"unidad":"g"},{"nombre":"Aceite de oliva","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5},{"nombre":"Pan integral","cantidad":1,"unidad":"rebanada","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1}]'::jsonb, '["Calienta el aceite en un sartén antiadherente.","Saltea la cebolla, calabacita y pimiento por 3-4 minutos.","Bate las claras con un poco de pimienta y viértelas sobre las verduras.","Cocina a fuego bajo tapado por 5 minutos hasta que cuaje.","Voltea con ayuda de un plato y cocina 2 minutos más.","Sirve con el pan integral tostado."]'::jsonb, 1, '{"kcal":245,"cho":22,"prot":22,"grasas":8,"fibra":3,"sodio":250}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Gluten","Huevo"],"vitaminas":[],"aptaParaDietas":[]}'::jsonb, '["Dislipidemia","Diabetes 2","Hipertensión","SOP"]'::jsonb, '["sin_lactosa","baja_en_grasa"]'::jsonb, '["alta_en_proteina","baja_en_grasa","baja_en_colesterol"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Sopa de Verduras con Pollo Desmenuzado', 'Cena ligera y reconfortante. Textura suave apta para dificultad masticatoria.', 'cena', 'facil', 20, 'sistema', '[{"nombre":"Pechuga de pollo cocida desmenuzada","cantidad":60,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":1.5},{"nombre":"Calabacita en cubos","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Zanahoria en cubos pequeños","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Papa en cubos","cantidad":40,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1},{"nombre":"Caldo de pollo bajo en sodio","cantidad":300,"unidad":"ml"}]'::jsonb, '["Hierve el caldo de pollo bajo en sodio.","Agrega la zanahoria y papa. Cocina 10 minutos.","Incorpora la calabacita y cocina 5 minutos más.","Agrega el pollo desmenuzado y calienta 2 minutos.","Sirve caliente. Puedes licuar parcialmente si necesitas textura más suave."]'::jsonb, 1, '{"kcal":210,"cho":22,"prot":20,"grasas":4,"fibra":3,"sodio":100}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":[],"aptaParaDietas":[]}'::jsonb, '["Gastritis","Artritis","Osteoporosis/artrosis","Hipertensión"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio","baja_en_grasa"]'::jsonb, '["dieta_blanda","facil_digestion","reconfortante","baja_en_sodio"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Yogur Griego con Frutos Rojos y Granola', 'Colación rica en proteína y probióticos. Ideal como snack entre comidas.', 'colacion', 'facil', 3, 'sistema', '[{"nombre":"Yogur griego natural sin azúcar","cantidad":150,"unidad":"g","smae_id":"lacteos_descremados_bajos_grasas","racionesSmae":1},{"nombre":"Fresas o arándanos","cantidad":80,"unidad":"g","smae_id":"frutas_bajas_cho","racionesSmae":1},{"nombre":"Granola sin azúcar","cantidad":15,"unidad":"g","smae_id":"cereales_medios_cho_medios_grasas","racionesSmae":0.5}]'::jsonb, '["Coloca el yogur en un vaso o bowl.","Agrega los frutos rojos frescos o congelados.","Corona con la granola justo antes de consumir para mantener la textura."]'::jsonb, 1, '{"kcal":175,"cho":22,"prot":12,"grasas":4,"fibra":3,"sodio":65}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Lácteos"],"vitaminas":["Calcio","Vitamina C"],"aptaParaDietas":["Vegetariana"]}'::jsonb, '["Osteoporosis/artrosis","Hipotiroidismo","Lesión muscular"]'::jsonb, '["baja_en_grasa"]'::jsonb, '["rica_en_calcio","probioticos","rapida","snack"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Palitos de Jícama y Pepino con Limón y Chile', 'Snack fresco prácticamente libre en calorías. Hidratante y saciante.', 'colacion', 'facil', 5, 'sistema', '[{"nombre":"Jícama en palitos","cantidad":100,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Pepino en palitos","cantidad":100,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Limón","cantidad":1,"unidad":"pieza"},{"nombre":"Chile piquín en polvo (poco)","cantidad":1,"unidad":"pizca"}]'::jsonb, '["Pela y corta la jícama y el pepino en palitos delgados.","Exprime el limón por encima.","Espolvorea una pizca muy ligera de chile piquín.","Consume frío para mayor frescura."]'::jsonb, 1, '{"kcal":45,"cho":10,"prot":2,"grasas":0,"fibra":5,"sodio":10}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":["Vitamina C"],"aptaParaDietas":["Vegana","Vegetariana"]}'::jsonb, '["Diabetes 2","Diabetes 1","Hipertensión","Dislipidemia","Gastritis","SOP"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio","baja_en_grasa"]'::jsonb, '["libre","hidratante","rapida","sin_calorias"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Manzana con Crema de Cacahuate', 'Colación equilibrada con fibra y grasas saludables. Saciante y energizante.', 'colacion', 'facil', 3, 'sistema', '[{"nombre":"Manzana verde","cantidad":1,"unidad":"pieza","smae_id":"frutas_medias_cho","racionesSmae":1},{"nombre":"Crema de cacahuate natural","cantidad":15,"unidad":"g","smae_id":"grasas_altas_grasas_bajas_cho","racionesSmae":1}]'::jsonb, '["Lava y rebana la manzana en gajos.","Sirve con la crema de cacahuate para dippear.","Consume inmediatamente para evitar que la manzana se oxide."]'::jsonb, 1, '{"kcal":210,"cho":28,"prot":5,"grasas":10,"fibra":5,"sodio":30}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Nueces/Cacahuates"],"vitaminas":[],"aptaParaDietas":["Vegana","Vegetariana"]}'::jsonb, '["Diabetes 2","Hipotiroidismo","Lesión muscular","SOP"]'::jsonb, '["sin_lactosa","sin_gluten"]'::jsonb, '["rapida","snack","saciante","alta_en_fibra"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Ensalada de Atún con Aguacate (Sin Mayonesa)', 'Ensalada proteica ligera y cardiosaludable, sin grasas saturadas.', 'cena', 'facil', 8, 'sistema', '[{"nombre":"Atún en agua escurrido","cantidad":80,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":2},{"nombre":"Aguacate","cantidad":50,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":1.25},{"nombre":"Pepino picado","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Jitomate picado","cantidad":50,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Tostadas horneadas","cantidad":2,"unidad":"piezas","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":1},{"nombre":"Limón","cantidad":1,"unidad":"pieza"}]'::jsonb, '["Escurre el atún y colócalo en un bowl.","Machaca el aguacate y mézclalo con el atún (reemplaza la mayonesa).","Agrega pepino, jitomate picado y limón al gusto.","Sirve sobre las tostadas horneadas."]'::jsonb, 1, '{"kcal":330,"cho":25,"prot":22,"grasas":16,"fibra":5,"sodio":190}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Pescado"],"vitaminas":["Omega 3","Vitamina C"],"aptaParaDietas":[]}'::jsonb, '["Dislipidemia","Hipertensión","Diabetes 2","SOP"]'::jsonb, '["sin_lactosa","baja_en_grasa"]'::jsonb, '["rica_en_omega3","sin_mayonesa","rapida","cardiosaludable"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Puré de Camote con Pollo Desmenuzado', 'Comida de textura suave ideal para dificultad masticatoria. Nutritiva y reconfortante.', 'almuerzo', 'facil', 25, 'sistema', '[{"nombre":"Camote cocido","cantidad":120,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":2.5},{"nombre":"Pechuga de pollo cocida y desmenuzada","cantidad":80,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":2},{"nombre":"Mantequilla sin sal","cantidad":5,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":0.5},{"nombre":"Leche descremada","cantidad":30,"unidad":"ml","smae_id":"lacteos_descremados_bajos_grasas","racionesSmae":0.25}]'::jsonb, '["Cocina el camote hasta que esté muy suave (hervido o al vapor).","Machácalo con mantequilla y leche hasta obtener un puré cremoso.","Hierve la pechuga y desmenúzala en hebras muy finas.","Sirve el puré con el pollo desmenuzado encima."]'::jsonb, 1, '{"kcal":340,"cho":42,"prot":25,"grasas":8,"fibra":4,"sodio":80}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Lácteos"],"vitaminas":[],"aptaParaDietas":[]}'::jsonb, '["Gastritis","Artritis","Osteoporosis/artrosis"]'::jsonb, '["sin_gluten","baja_en_sodio"]'::jsonb, '["dieta_blanda","facil_digestion","reconfortante","textura_suave"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Agua de Jamaica sin Azúcar con Chía', 'Bebida antioxidante rica en fibra. Hidratante y saciante sin calorías vacías.', 'bebida', 'facil', 15, 'sistema', '[{"nombre":"Flor de Jamaica seca","cantidad":15,"unidad":"g"},{"nombre":"Semillas de chía","cantidad":10,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":0.5},{"nombre":"Agua","cantidad":500,"unidad":"ml"},{"nombre":"Stevia o sin endulzar","cantidad":1,"unidad":"sobre"}]'::jsonb, '["Hierve la flor de Jamaica en el agua por 5 minutos.","Cuela y deja enfriar. Endulza con stevia si lo deseas.","Agrega las semillas de chía y deja hidratar 10 minutos.","Revuelve bien antes de servir con hielos."]'::jsonb, 2, '{"kcal":35,"cho":3,"prot":1,"grasas":2,"fibra":4,"sodio":5}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":[],"aptaParaDietas":["Vegana","Vegetariana"]}'::jsonb, '["Diabetes 2","Diabetes 1","Hipertensión","Dislipidemia","SOP","Gastritis"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio","sin_azucar"]'::jsonb, '["sin_azucar","antioxidante","hidratante","alta_en_fibra"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Gelatina de Frutas Naturales sin Azúcar', 'Postre saludable bajo en calorías. Aporta proteína del colágeno.', 'postre_saludable', 'facil', 10, 'sistema', '[{"nombre":"Gelatina sin sabor","cantidad":7,"unidad":"g"},{"nombre":"Fresas picadas","cantidad":100,"unidad":"g","smae_id":"frutas_bajas_cho","racionesSmae":1},{"nombre":"Jugo de naranja natural","cantidad":200,"unidad":"ml","smae_id":"frutas_medias_cho","racionesSmae":1},{"nombre":"Stevia","cantidad":1,"unidad":"sobre"}]'::jsonb, '["Hidrata la gelatina sin sabor en 50ml de agua fría por 5 minutos.","Calienta el jugo de naranja sin hervir y disuelve la gelatina.","Agrega las fresas picadas y endulza con stevia.","Vierte en moldes y refrigera mínimo 2 horas."]'::jsonb, 2, '{"kcal":70,"cho":14,"prot":4,"grasas":0,"fibra":2,"sodio":10}'::jsonb, '{"cargaGlicemica":"media","alergenos":[],"vitaminas":["Vitamina C"],"aptaParaDietas":["Vegana","Vegetariana"]}'::jsonb, '["Diabetes 2","Diabetes 1","Gastritis","Osteoporosis/artrosis","Hipertensión"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_sodio","sin_azucar","baja_en_grasa"]'::jsonb, '["sin_azucar","postre","baja_en_calorias","facil_digestion"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Chilaquiles Verdes Saludables con Claras', 'Versión saludable del clásico mexicano. Baja en grasa, alta en proteína.', 'desayuno', 'media', 20, 'sistema', '[{"nombre":"Tortillas de maíz horneadas (no fritas)","cantidad":3,"unidad":"piezas","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":3},{"nombre":"Salsa verde casera","cantidad":100,"unidad":"ml"},{"nombre":"Claras de huevo","cantidad":3,"unidad":"piezas","smae_id":"carnes_bajas_grasas","racionesSmae":1.5},{"nombre":"Queso fresco desmoronado","cantidad":20,"unidad":"g","smae_id":"lacteos_quesos","racionesSmae":0.5},{"nombre":"Crema ácida light","cantidad":10,"unidad":"g"},{"nombre":"Cebolla y cilantro","cantidad":10,"unidad":"g"}]'::jsonb, '["Corta las tortillas en triángulos y hornéalas a 180°C por 8-10 minutos (en lugar de freírlas).","Calienta la salsa verde en un sartén.","Agrega los totopos horneados y mezcla para que se impregnen de salsa.","Cocina las claras de huevo revueltas en otro sartén.","Sirve los chilaquiles con las claras, queso fresco y un toque de crema light."]'::jsonb, 1, '{"kcal":340,"cho":42,"prot":22,"grasas":9,"fibra":4,"sodio":280}'::jsonb, '{"cargaGlicemica":"media","alergenos":["Lácteos","Huevo"],"vitaminas":[],"aptaParaDietas":[]}'::jsonb, '["Diabetes 2","Dislipidemia","Hipotiroidismo","SOP"]'::jsonb, '["baja_en_grasa"]'::jsonb, '["mexicana","alta_en_proteina","baja_en_grasa","horneado"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Pizza Keto con Base de Coliflor', 'Pizza baja en carbohidratos, excelente para dieta cetogénica y diabéticos.', 'cena', 'media', 35, 'sistema', '[{"nombre":"Coliflor rallada","cantidad":150,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":2},{"nombre":"Queso mozzarella bajo en grasa","cantidad":50,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":1.5},{"nombre":"Huevo","cantidad":1,"unidad":"pieza","smae_id":"carnes_medias_grasas","racionesSmae":1},{"nombre":"Salsa de tomate casera","cantidad":30,"unidad":"ml","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Champiñones y espinaca","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1}]'::jsonb, '["Exprime bien la coliflor rallada para quitar todo el líquido.","Mezcla la coliflor con medio huevo y la mitad del queso para formar la masa.","Extiende en una charola y hornea a 200°C por 15 min hasta que dore.","Agrega la salsa, el resto del queso y los vegetales.","Hornea 10 minutos más."]'::jsonb, 1, '{"kcal":280,"cho":12,"prot":22,"grasas":16,"fibra":5,"sodio":350}'::jsonb, '{"cargaGlicemica":"baja","alergenos":["Lácteos","Huevo"],"vitaminas":["Calcio","Vitamina C"],"aptaParaDietas":["Keto","Vegetariana"]}'::jsonb, '["Diabetes 1","Diabetes 2","SOP","Osteoporosis/artrosis"]'::jsonb, '["sin_gluten","sin_azucar"]'::jsonb, '["bajo_indice_glucemico","horneado","alta_en_proteina"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Filete de Pescado Empapelado con Vegetales', 'Comida muy baja en grasa y fácil de digerir. Ideal para gastritis.', 'almuerzo', 'facil', 25, 'sistema', '[{"nombre":"Filete de pescado blanco","cantidad":120,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":3},{"nombre":"Calabacita en rodajas","cantidad":80,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Zanahoria en rodajas finas","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Arroz blanco cocido","cantidad":40,"unidad":"g","smae_id":"cereales_altos_cho_bajos_grasas","racionesSmae":1},{"nombre":"Aceite de oliva","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5}]'::jsonb, '["Sobre papel aluminio, coloca una capa de vegetales.","Pon el filete de pescado encima y rocía con el aceite de oliva, sal (poca) y hierbas finas.","Cierra el papel aluminio formando un paquete hermético.","Cocina en un sartén o comal a fuego medio-bajo por 15 minutos.","Sirve acompañado del arroz blanco."]'::jsonb, 1, '{"kcal":280,"cho":22,"prot":30,"grasas":8,"fibra":3,"sodio":120}'::jsonb, '{"cargaGlicemica":"baja","alergenos":["Pescado"],"vitaminas":["Omega 3"],"aptaParaDietas":["Pescatariana"]}'::jsonb, '["Gastritis","Hipertensión","Dislipidemia"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_grasa","baja_en_sodio"]'::jsonb, '["dieta_blanda","facil_digestion","alta_en_proteina"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Ensalada de Lentejas Mediterránea', 'Almuerzo vegano rico en hierro y fibra. Control cardiovascular.', 'almuerzo', 'facil', 15, 'sistema', '[{"nombre":"Lentejas cocidas","cantidad":120,"unidad":"g","smae_id":"leguminosas","racionesSmae":2},{"nombre":"Tomate cherry","cantidad":60,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":1},{"nombre":"Pepino picado","cantidad":50,"unidad":"g","smae_id":"vegetales_libre","racionesSmae":1},{"nombre":"Aceitunas negras","cantidad":20,"unidad":"g","smae_id":"grasas_altas_grasas","racionesSmae":1},{"nombre":"Aceite de oliva y limón","cantidad":5,"unidad":"ml","smae_id":"grasas_altas_grasas","racionesSmae":0.5}]'::jsonb, '["En un bowl grande mezcla las lentejas cocidas (frías) con el pepino y tomate.","Agrega las aceitunas rebanadas.","Prepara una vinagreta sencilla con aceite de oliva, jugo de limón, sal y pimienta.","Mezcla todo y deja reposar 5 minutos antes de comer."]'::jsonb, 1, '{"kcal":310,"cho":38,"prot":14,"grasas":12,"fibra":14,"sodio":200}'::jsonb, '{"cargaGlicemica":"baja","alergenos":[],"vitaminas":["Hierro","Vitamina C"],"aptaParaDietas":["Vegana","Vegetariana","Mediterránea"]}'::jsonb, '["Diabetes 2","Dislipidemia","Hipertensión"]'::jsonb, '["sin_lactosa","sin_gluten","baja_en_grasa"]'::jsonb, '["alta_en_fibra","rica_en_hierro","cardiosaludable","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Muffins de Huevo y Espinaca', 'Desayuno rápido preparado con anticipación. Perfecto para llevar.', 'desayuno', 'facil', 25, 'sistema', '[{"nombre":"Huevo","cantidad":2,"unidad":"piezas","smae_id":"carnes_medias_grasas","racionesSmae":2},{"nombre":"Espinaca picada","cantidad":40,"unidad":"g","smae_id":"vegetales_bajos_cho","racionesSmae":0.5},{"nombre":"Queso panela rallado","cantidad":20,"unidad":"g","smae_id":"carnes_bajas_grasas","racionesSmae":0.5},{"nombre":"Avena en polvo","cantidad":15,"unidad":"g","smae_id":"cereales_medios_cho_bajos_grasas","racionesSmae":0.5}]'::jsonb, '["Precalienta el horno a 180°C y engrasa moldes para muffin.","Bate los huevos y mezcla con la avena, espinaca y queso.","Vierte la mezcla en 2 o 3 capacillos.","Hornea por 15-20 minutos hasta que estén dorados y firmes."]'::jsonb, 1, '{"kcal":240,"cho":12,"prot":20,"grasas":13,"fibra":3,"sodio":250}'::jsonb, '{"cargaGlicemica":"baja","alergenos":["Huevo","Lácteos"],"vitaminas":["Calcio","Hierro"],"aptaParaDietas":["Vegetariana"]}'::jsonb, '["SOP","Osteoporosis/artrosis","Diabetes 2"]'::jsonb, '["sin_gluten"]'::jsonb, '["alta_en_proteina","horneado","rapida"]'::jsonb);
INSERT INTO public.recipes (nombre, descripcion, categoria, dificultad, tiempo_preparacion_min, origen, ingredientes, instrucciones, porciones_rinde, macros_por_porcion, datos_nutricionales_avanzados, apta_para_condiciones, restricciones, tags) VALUES ('Té de Manzanilla con Jengibre', 'Bebida relajante y digestiva. Excelente antes de dormir o para gastritis.', 'bebida', 'facil', 10, 'sistema', '[{"nombre":"Flores de manzanilla o bolsita","cantidad":1,"unidad":"sobre"},{"nombre":"Jengibre fresco en rodajas","cantidad":5,"unidad":"g"},{"nombre":"Agua","cantidad":250,"unidad":"ml"}]'::jsonb, '["Hierve el agua junto con las rodajas de jengibre por 5 minutos.","Apaga el fuego, agrega la manzanilla y deja reposar 3 minutos tapado.","Cuela y sirve caliente. No agregar azúcar."]'::jsonb, 1, '{"kcal":5,"cho":1,"prot":0,"grasas":0,"fibra":0,"sodio":0}'::jsonb, '{"cargaGlicemica":"baja","alergenos":[],"vitaminas":[],"aptaParaDietas":["Vegana","Vegetariana","Keto","Mediterránea"]}'::jsonb, '["Gastritis","Artritis","Hipertensión","Diabetes 1","Diabetes 2","SOP"]'::jsonb, '["sin_lactosa","sin_gluten","sin_azucar","baja_en_sodio"]'::jsonb, '["antiinflamatoria","reconfortante","facil_digestion","sin_calorias"]'::jsonb);
